*
 * POST /admin/accessories.json
 *
 * Examples:
 *
 *      insales.createAccessory({
 *        token: '1234567890',
 *        url: 'shop-test.myinsales.ru',
 *        accessory: {
 *          "accessory": {
 *            "name": "Опция 1",
 *            "max_count": 7,
 *            "min_count": 3,
 *            "permalink": "opcia-1"
 *          }
 *        }
 *      }).then(response => {
 *        console.info(response.data);
 *      }).catch(err => {
 *        console.error(err);
 *      });
 * Output:
 *
 *      {
 *        "id": 58,
 *        "account_id": 1,
 *        "name_translations": [
 *          "Опция 1"
 *        ],
 *        "min_count": 3,
 *        "max_count": 7,
 *        "created_at": "2026-10-21T23:15:57.629+03:00",
 *        "updated_at": "2026-10-21T23:15:57.629+03:00",
 *        "back_office_name": "Опция 1",
 *        "permalink": "opcia-1",
 *        "name": "Опция 1"
 *      }
 * @param {Object} options
 * @param {string} options.token Required, access token for shop
 * @param {string} options.url Required, shop url
 * @param {object} options.accessory Required, accessory
 * @param {Number|String} id Required, app id
 * @returns {Promise}

